import { test } from "node:test";
import assert from "node:assert/strict";
import { unitOutcome } from "../src/core/operation_runner_execution.js";

const OUTCOMES = ["VERIFIED", "NOT_REQUIRED", "REGRESSION_FREE", "UNVERIFIED"] as const;
const ROLES = ["tester", "implementer", "reviewer", "planner"] as const;

test("only a tester's NOT_REQUIRED turn with a verifier run this turn becomes VERIFIED; nothing else changes", () => {
  for (const role of ROLES) {
    for (const outcome of OUTCOMES) {
      for (const ran of [true, false]) {
        const expected = role === "tester" && outcome === "NOT_REQUIRED" && ran ? "VERIFIED" : outcome;
        assert.equal(unitOutcome({ role } as any, { outcome } as any, ran), expected, `${role} ${outcome} ran=${ran}`);
      }
    }
  }
});
