const DEFAULT_PORT = 8080;

function parsePort(raw) {
  if (raw === undefined || raw === null) return DEFAULT_PORT;
  const text = String(raw).trim();
  // An empty or blank PORT must fall back to the default. Number("") is 0, which would pass the range check below as
  // a "valid" port and make the server listen on a random one: this guard is why `PORT=` in a .env file is safe.
  if (text === "") return DEFAULT_PORT;
  const n = Number(text);
  if (!Number.isInteger(n)) return DEFAULT_PORT;
  if (n < 1 || n > 65535) return DEFAULT_PORT;
  return n;
}
module.exports = { parsePort, DEFAULT_PORT };
')
