// docs/INVARIANTS.md I-PROVIDER-3: a connection that never makes a tool call is reported, not silently tool-less.
test("a server that writes the call as text even when a call is required is reported once as not tool-capable", async () => {
  const warned: string[] = [];
  const original = console.warn;
  console.warn = (...a: unknown[]) => { warned.push(String(a[0])); };
  try {
    await withServer(() => textCall, async (client) => {
      assert.equal(client.getObservedToolCalls(), "unknown");
      await client.chatCompletion([user("run echo ok")], only("run_command"));
      assert.equal(client.getObservedToolCalls(), "text_only");
      await client.chatCompletion([user("run echo ok again")], only("run_command"));
      assert.equal(warned.filter((w) => /did not make a tool call even when one was required/.test(w)).length, 1, "said once, not on every turn");
    });
  } finally { console.warn = original; }
});

test("a server that makes the native call when asked again is observed as tool-capable and nothing is reported", async () => {
  const warned: string[] = [];
  const original = console.warn;
  console.warn = (...a: unknown[]) => { warned.push(String(a[0])); };
  try {
    await withServer((seen) => (seen.toolChoice === "required" ? nativeCall : textCall), async (client) => {
      await client.chatCompletion([user("run echo ok")], only("run_command"));
      assert.equal(client.getObservedToolCalls(), "native");
      assert.equal(warned.some((w) => /did not make a tool call/.test(w)), false);
    });
  } finally { console.warn = original; }
});

test("a failed forced request says nothing about tool support", async () => {
  await withServer((seen) => (seen.toolChoice === "required" ? { __status: 400 } : textCall), async (client) => {
    await client.chatCompletion([user("run echo ok")], only("run_command"));
    assert.equal(client.getObservedToolCalls(), "unknown");
  });
});
EOF
